<section class="section"><div class="section-header"><h1>Backups</h1><form action="/admin/backup" method="post"><?= \App\Util\Csrf::field() ?><button class="button" type="submit">Create backup</button></form></div><div class="card-list"><?php foreach ($backups as $backup): ?><article class="card"><h2><?= e($backup['name']) ?></h2><p><?= e(number_format(($backup['size'] ?? 0) / 1024, 1)) ?> KB</p><p class="muted"><?= e(format_datetime((int) ($backup['created_at'] ?? 0))) ?></p></article><?php endforeach; ?></div></section>
